#include <unordered_map>
#include <list>
using namespace std;

// A classic O(1) get and put LRU cache using a hashmap paired with a
// doubly linked list ordered by recency of access.
template <typename K, typename V>
class LRUCache {
    int capacity;
    list<pair<K, V>> items; // front is most recently used
    unordered_map<K, typename list<pair<K, V>>::iterator> map;

public:
    LRUCache(int cap) : capacity(cap) {}

    bool get(const K& key, V& outValue) {
        auto it = map.find(key);
        if (it == map.end()) return false;
        items.splice(items.begin(), items, it->second);
        outValue = it->second->second;
        return true;
    }

    void put(const K& key, const V& value) {
        auto it = map.find(key);
        if (it != map.end()) {
            it->second->second = value;
            items.splice(items.begin(), items, it->second);
            return;
        }
        if ((int)items.size() >= capacity) {
            auto last = items.back();
            map.erase(last.first);
            items.pop_back();
        }
        items.push_front({key, value});
        map[key] = items.begin();
    }
};

