import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;

// Ensures that if many callers request the same missing key at nearly the
// same moment, only one of them actually performs the expensive fetch,
// while the rest share that single fetch's result.
public class HotKeyCoalescer<V> {
    private final Map<String, CompletableFuture<V>> inFlight = new ConcurrentHashMap<>();

    public CompletableFuture<V> fetch(String key, java.util.function.Supplier<V> loader) {
        return inFlight.computeIfAbsent(key, k -> {
            CompletableFuture<V> future = CompletableFuture.supplyAsync(loader);
            future.whenComplete((result, error) -> inFlight.remove(key));
            return future;
        });
    }
}

