#include <functional>
#include <future>
#include <map>
#include <memory>
#include <mutex>
#include <string>
#include <thread>

// Ensures that if many callers request the same missing key at nearly the
// same moment, only one of them actually performs the expensive fetch,
// while the rest share that single fetch's result.
template <typename V>
class HotKeyCoalescer {
public:
    std::shared_future<V> fetch(const std::string& key, std::function<V()> loader) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = inFlight_.find(key);
        if (it != inFlight_.end()) return it->second;

        auto promise = std::make_shared<std::promise<V>>();
        std::shared_future<V> future = promise->get_future().share();
        inFlight_[key] = future;

        std::thread([this, key, loader, promise]() {
            V result = loader();
            promise->set_value(result);
            std::lock_guard<std::mutex> lock(mutex_);
            inFlight_.erase(key);
        }).detach();

        return future;
    }

private:
    std::map<std::string, std::shared_future<V>> inFlight_;
    std::mutex mutex_;
};

